=## 🤖 AI PR Review: {{ $('AI Agent').item.json.output.verdict.toUpperCase() }}

**Summary:** {{ $('AI Agent').item.json.output.summary }}

**Issues found:** {{ $('AI Agent').item.json.output.issues.length }}
{{ $('AI Agent').item.json.output.issues.map(i => `- **[${i.severity.toUpperCase()}]** \`${i.file}\` (line ${i.line}): ${i.description}`).join('\n') }}

---
*Automated review. See inline comments on the diff for issue locations.*

parameters.jsCode:
const rawDiff = $('Get a pull request diff').item.json.diff;
const issues = $('AI Agent').item.json.output.issues;
const commitSha = $('Github Trigger').item.json.body.pull_request.head.sha;

// Build a map: filename -> [{ fileLine, diffPosition }]
// GitHub's review comment API needs 'position': the line's position counted
// from the start of the diff hunk, not the file's actual line number.
function buildPositionMap(diffText) {
  const files = {};
  const lines = diffText.split('\n');
  let currentFile = null;
  let diffPosition = 0;
  let newLineNum = 0;

  for (const line of lines) {
    if (line.startsWith('diff --git')) {
      const match = line.match(/b\/(.+)$/);
      currentFile = match ? match[1].trim() : null;
      diffPosition = 0;
      if (currentFile && !files[currentFile]) files[currentFile] = [];
    } else if (line.startsWith('@@')) {
      diffPosition++;
      const m = line.match(/\+(\d+)/);
      newLineNum = m ? parseInt(m[1], 10) : 0;
    } else if (line.startsWith('+++') || line.startsWith('---') || line.startsWith('index ')) {
      // metadata lines, not counted toward position
    } else if (line.startsWith('+')) {
      diffPosition++;
      if (currentFile) files[currentFile].push({ fileLine: newLineNum, diffPosition });
      newLineNum++;
    } else if (line.startsWith('-')) {
      diffPosition++;
      // removed line: counts toward position but has no new-file line number
    } else {
      diffPosition++;
      if (currentFile) files[currentFile].push({ fileLine: newLineNum, diffPosition });
      newLineNum++;
    }
  }
  return files;
}

const positionMap = buildPositionMap(rawDiff);

const results = [];
for (const issue of issues) {
  const fileEntries = positionMap[issue.file];
  if (!fileEntries || fileEntries.length === 0) continue; // file not in diff, can't anchor a comment

  // pick the entry whose file line is closest to the LLM's guessed line
  let best = fileEntries[fileEntries.length - 1];
  let bestDiff = Infinity;
  for (const entry of fileEntries) {
    const d = Math.abs(entry.fileLine - (issue.line || entry.fileLine));
    if (d < bestDiff) {
      bestDiff = d;
      best = entry;
    }
  }

  results.push({
    json: {
      path: issue.file,
      position: best.diffPosition,
      body: `**[${issue.severity.toUpperCase()}]** ${issue.description}`,
      commit_id: commitSha
    }
  });
}

return results;

const diffText = $input.first().json.diff;

// Pull PR metadata from the original GitHub Trigger payload
const trigger = $('Github Trigger').first().json.body;

const prNumber = trigger.pull_request.number;
const prTitle = trigger.pull_request.title;
const prAuthor = trigger.pull_request.user.login;
const repoFullName = trigger.repository.full_name;

// Truncate diff if it's huge, so it doesn't blow the LLM context window
const MAX_DIFF_LENGTH = 8000;
const truncated = diffText.length > MAX_DIFF_LENGTH;
const formattedDiff = truncated
  ? diffText.slice(0, MAX_DIFF_LENGTH) + '\n\n... [diff truncated, too large to show in full]'
  : diffText;

return [{
  json: {
    prNumber,
    prTitle,
    prAuthor,
    repoFullName,
    formattedDiff,
    truncated
  }
}];
